<?php
declare(strict_types=1);namespace NpmGateway\Repositories;use mysqli;
final class CreditCardPurchaseRepository{private ?int $corporateSubmitterScope=null;public function __construct(private readonly mysqli $db){}public function scopeCorporateSubmitter(int $userId):void{$this->corporateSubmitterScope=$userId;}
 public function activeExpenseProperties():array{return $this->db->query("SELECT id,public_id,slug,property_code,display_name FROM properties WHERE status='active' ORDER BY (property_code='CO') DESC,display_name,id")->fetch_all(MYSQLI_ASSOC);}
 public function activePropertyByPublicId(string $public):?array{$s=$this->db->prepare("SELECT id,public_id,slug,property_code,display_name FROM properties WHERE public_id=? AND status='active' LIMIT 1");$s->bind_param('s',$public);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return is_array($row)?$row:null;}
 public function propertyIdentity(int $id):?array{$s=$this->db->prepare("SELECT id,public_id,display_name FROM properties WHERE id=? LIMIT 1");$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return is_array($row)?$row:null;}
 public function activeEmployees():array{$rows=$this->db->query("SELECT e.id,e.public_id,CONCAT(COALESCE(NULLIF(e.preferred_name,''),e.first_name),' ',e.last_name) display_name,CASE WHEN e.employee_class='corporate' THEN 'Corporate' WHEN EXISTS(SELECT 1 FROM employee_property_assignments a WHERE a.employee_id=e.id AND a.assignment_type='assistant_manager' AND a.starts_on<=CURRENT_DATE AND a.ends_on IS NULL) THEN 'Assistant Managers' WHEN e.employee_class='manager' THEN 'Managers' ELSE 'Maintenance' END role_group FROM employees e WHERE e.employment_status='active' ORDER BY FIELD(role_group,'Corporate','Managers','Assistant Managers','Maintenance'),display_name,e.id")->fetch_all(MYSQLI_ASSOC);return $rows;}
 public function activeEmployeeByPublicId(string $public):?array{$s=$this->db->prepare("SELECT id,public_id,CONCAT(COALESCE(NULLIF(preferred_name,''),first_name),' ',last_name) display_name FROM employees WHERE public_id=? AND employment_status='active' LIMIT 1");$s->bind_param('s',$public);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return is_array($row)?$row:null;}
 public function eligibleEmployees(int $property):array{$s=$this->db->prepare("SELECT e.id,e.public_id,CONCAT(COALESCE(NULLIF(e.preferred_name,''),e.first_name),' ',e.last_name) display_name,e.employee_class,MIN(CASE WHEN a.assignment_type='property_manager' THEN 1 WHEN a.assignment_type='assistant_manager' THEN 2 WHEN a.assignment_type='maintenance' THEN 3 WHEN e.employee_class='manager' THEN 1 ELSE 3 END) role_order FROM employees e JOIN employee_property_assignments a ON a.employee_id=e.id WHERE a.property_id=? AND a.starts_on<=CURRENT_DATE AND a.ends_on IS NULL AND e.employment_status='active' GROUP BY e.id,e.public_id,e.preferred_name,e.first_name,e.last_name,e.employee_class ORDER BY role_order,display_name,e.id");$s->bind_param('i',$property);$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();foreach($r as &$employee)$employee['role_group']=match((int)$employee['role_order']){1=>'Managers',2=>'Assistant Managers',default=>'Maintenance'};unset($employee);return $r;}
 public function insert(array $r):int{$s=$this->db->prepare("INSERT INTO credit_card_purchases(public_id,property_id,card_last_four,purchase_date,amount,purchased_by_employee_id,submitted_by_user_id,vendor,description,receipt_status,missing_receipt_reason,status,submitted_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'posted',?,?)");$s->bind_param('sisssiissssss',$r['public_id'],$r['property_id'],$r['card_last_four'],$r['purchase_date'],$r['amount'],$r['purchaser_id'],$r['submitter_id'],$r['vendor'],$r['description'],$r['receipt_status'],$r['missing_reason'],$r['timestamp'],$r['timestamp']);$s->execute();$id=(int)$this->db->insert_id;$s->close();return $id;}
 public function history(int $id,string $public,string $event,int $actor,array $metadata,?string $comments,string $at):void{$json=json_encode($metadata,JSON_THROW_ON_ERROR);$s=$this->db->prepare('INSERT INTO credit_card_purchase_history(public_id,purchase_id,event_type,actor_user_id,metadata,comments,created_at) VALUES(?,?,?,?,?,?,?)');$s->bind_param('sisisss',$public,$id,$event,$actor,$json,$comments,$at);$s->execute();$s->close();}
 public function list(int $property,string $search='',string $receipt=''):array{[$where,$types,$args]=$this->filteredWhere($property,$search,$receipt);$sql="SELECT p.public_id,p.purchase_date,p.card_last_four,p.amount,p.vendor,p.receipt_status,p.updated_at,CONCAT(e.first_name,' ',e.last_name) purchased_by_name FROM credit_card_purchases p JOIN employees e ON e.id=p.purchased_by_employee_id {$where} ORDER BY p.purchase_date DESC,p.submitted_at DESC,p.id DESC";$s=$this->db->prepare($sql);$s->bind_param($types,...$args);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return $rows;}
 public function summary(int $property,string $search='',string $receipt=''):array{[$where,$types,$args]=$this->filteredWhere($property,$search,$receipt);$s=$this->db->prepare("SELECT COUNT(*) total,COALESCE(SUM(p.amount),0.00) total_posted,SUM(p.receipt_status='attached') attached,SUM(p.receipt_status='missing') missing FROM credit_card_purchases p JOIN employees e ON e.id=p.purchased_by_employee_id {$where}");$s->bind_param($types,...$args);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return ['total'=>(int)$row['total'],'total_posted'=>(string)$row['total_posted'],'attached'=>(int)$row['attached'],'missing'=>(int)$row['missing']];}
 public function companyList(int $submitter,string $search='',?int $property=null,string $receipt=''):array{[$where,$types,$args]=$this->companyWhere($submitter,$search,$property,$receipt);$s=$this->db->prepare("SELECT p.public_id,p.purchase_date,p.card_last_four,p.amount,p.vendor,p.receipt_status,p.updated_at,prop.display_name property_name,CONCAT(pe.first_name,' ',pe.last_name) purchased_by_name,CONCAT(se.first_name,' ',se.last_name) submitted_by_name FROM credit_card_purchases p JOIN properties prop ON prop.id=p.property_id JOIN employees pe ON pe.id=p.purchased_by_employee_id JOIN users su ON su.id=p.submitted_by_user_id JOIN employees se ON se.id=su.employee_id {$where} ORDER BY p.purchase_date DESC,p.submitted_at DESC,p.id DESC");$s->bind_param($types,...$args);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return $rows;}
 public function companySummary(int $submitter,string $search='',?int $property=null,string $receipt=''):array{[$where,$types,$args]=$this->companyWhere($submitter,$search,$property,$receipt);$s=$this->db->prepare("SELECT COUNT(*) total,COALESCE(SUM(p.amount),0.00) total_posted,SUM(p.receipt_status='attached') attached,SUM(p.receipt_status='missing') missing FROM credit_card_purchases p JOIN properties prop ON prop.id=p.property_id JOIN employees pe ON pe.id=p.purchased_by_employee_id JOIN users su ON su.id=p.submitted_by_user_id JOIN employees se ON se.id=su.employee_id {$where}");$s->bind_param($types,...$args);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return ['total'=>(int)$row['total'],'total_posted'=>(string)$row['total_posted'],'attached'=>(int)$row['attached'],'missing'=>(int)$row['missing']];}
 public function detail(string $public,int $property,bool $lock=false):?array{$sql="SELECT p.*,pr.public_id receipt_public_id,pr.uploaded_at receipt_uploaded_at,s.public_id storage_public_id,s.display_filename receipt_filename,s.mime_type receipt_mime,s.byte_size receipt_bytes,pe.public_id purchased_by_employee_public_id,CONCAT(pe.first_name,' ',pe.last_name) purchased_by_name,CONCAT(se.first_name,' ',se.last_name) submitted_by_name,CONCAT(re.first_name,' ',re.last_name) receipt_uploaded_by_name,prop.display_name property_name FROM credit_card_purchases p JOIN properties prop ON prop.id=p.property_id JOIN employees pe ON pe.id=p.purchased_by_employee_id JOIN users su ON su.id=p.submitted_by_user_id JOIN employees se ON se.id=su.employee_id LEFT JOIN credit_card_purchase_receipts pr ON pr.purchase_id=p.id AND pr.superseded_at IS NULL LEFT JOIN storage_objects s ON s.id=pr.storage_object_id LEFT JOIN users ru ON ru.id=pr.uploaded_by_user_id LEFT JOIN employees re ON re.id=ru.employee_id WHERE p.public_id=? AND p.property_id=? LIMIT 1".($lock?' FOR UPDATE':'');$s=$this->db->prepare($sql);$s->bind_param('si',$public,$property);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if(!is_array($r))return null;$r['history']=$this->historyRows((int)$r['id']);return $r;}
 public function companyDetail(string $public,int|bool|null $submitter=null,bool $lock=false):?array{if(is_bool($submitter)){$lock=$submitter;$submitter=$this->corporateSubmitterScope;}$submitter??=$this->corporateSubmitterScope;if(!$submitter)return null;$s=$this->db->prepare("SELECT property_id FROM credit_card_purchases WHERE public_id=? AND submitted_by_user_id=? LIMIT 1".($lock?' FOR UPDATE':''));$s->bind_param('si',$public,$submitter);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!is_array($row))return null;$detail=$this->detail($public,(int)$row['property_id'],$lock);$identity=$this->propertyIdentity((int)$row['property_id']);if($detail&&$identity)$detail['property_public_id']=$identity['public_id'];return $detail;}
 public function currentReceiptDocument(string $purchasePublic,string $receiptPublic,int $property):?array{$s=$this->db->prepare("SELECT pr.public_id receipt_public_id,p.public_id purchase_public_id,s.public_id storage_public_id,s.display_filename,s.mime_type,s.byte_size FROM credit_card_purchases p JOIN credit_card_purchase_receipts pr ON pr.purchase_id=p.id AND pr.superseded_at IS NULL JOIN storage_objects s ON s.id=pr.storage_object_id AND s.lifecycle_state='published' WHERE p.public_id=? AND pr.public_id=? AND p.property_id=? LIMIT 1");$s->bind_param('ssi',$purchasePublic,$receiptPublic,$property);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return is_array($row)?$row:null;}
 public function companyReceiptDocument(string $purchasePublic,string $receiptPublic,int $submitter):?array{$s=$this->db->prepare("SELECT pr.public_id receipt_public_id,p.public_id purchase_public_id,s.public_id storage_public_id,s.display_filename,s.mime_type,s.byte_size FROM credit_card_purchases p JOIN credit_card_purchase_receipts pr ON pr.purchase_id=p.id AND pr.superseded_at IS NULL JOIN storage_objects s ON s.id=pr.storage_object_id AND s.lifecycle_state='published' WHERE p.public_id=? AND pr.public_id=? AND p.submitted_by_user_id=? LIMIT 1");$s->bind_param('ssi',$purchasePublic,$receiptPublic,$submitter);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();return is_array($row)?$row:null;}
 public function historyRows(int $id):array{$s=$this->db->prepare("SELECT h.public_id,h.event_type,h.metadata,h.comments,h.created_at,CONCAT(e.first_name,' ',e.last_name) actor_name FROM credit_card_purchase_history h JOIN users u ON u.id=h.actor_user_id JOIN employees e ON e.id=u.employee_id WHERE h.purchase_id=? ORDER BY h.created_at,h.id");$s->bind_param('i',$id);$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();foreach($r as &$row)$row['metadata']=is_string($row['metadata'])?(json_decode($row['metadata'],true)?:[]):[];unset($row);return $r;}
 public function correct(int $id,array $r,string $at):void{$property=$r['property_id']??null;$s=$this->db->prepare("UPDATE credit_card_purchases SET property_id=COALESCE(?,property_id),card_last_four=?,purchase_date=?,amount=?,purchased_by_employee_id=?,vendor=?,description=?,missing_receipt_reason=?,status='corrected',updated_at=? WHERE id=? AND status IN ('posted','corrected')");$s->bind_param('isssissssi',$property,$r['card_last_four'],$r['purchase_date'],$r['amount'],$r['purchaser_id'],$r['vendor'],$r['description'],$r['missing_reason'],$at,$id);$s->execute();if($s->affected_rows!==1){$s->close();throw new \RuntimeException('This purchase cannot be corrected.');}$s->close();}
 public function linkReceipt(int $purchase,int $storage,int $user,string $public,string $at):void{$s=$this->db->prepare('INSERT INTO credit_card_purchase_receipts(public_id,purchase_id,storage_object_id,uploaded_by_user_id,uploaded_at) VALUES(?,?,?,?,?)');$s->bind_param('siiis',$public,$purchase,$storage,$user,$at);$s->execute();$s->close();}
 public function attachReceipt(int $purchase,int $storage,int $user,string $public,string $at):void{$s=$this->db->prepare("UPDATE credit_card_purchases SET receipt_status='attached',updated_at=? WHERE id=? AND receipt_status='missing'");$s->bind_param('si',$at,$purchase);$s->execute();if($s->affected_rows!==1)throw new \RuntimeException('A receipt is already attached.');$s->close();$this->linkReceipt($purchase,$storage,$user,$public,$at);}
 private function filteredWhere(int $property,string $search,string $receipt):array{$where="WHERE p.property_id=? AND p.status<>'voided'";$types='i';$args=[$property];if($search!==''){$where.=" AND (p.vendor LIKE ? OR p.description LIKE ? OR CONCAT(e.first_name,' ',e.last_name) LIKE ? OR p.card_last_four LIKE ?)";$q='%'.$search.'%';$types.='ssss';array_push($args,$q,$q,$q,$q);}if(in_array($receipt,['attached','missing'],true)){$where.=' AND p.receipt_status=?';$types.='s';$args[]=$receipt;}return [$where,$types,$args];}
 private function companyWhere(int $submitter,string $search,?int $property,string $receipt):array{$where="WHERE p.submitted_by_user_id=? AND p.status<>'voided'";$types='i';$args=[$submitter];if($property!==null){$where.=' AND p.property_id=?';$types.='i';$args[]=$property;}if($search!==''){$where.=" AND (p.vendor LIKE ? OR p.description LIKE ? OR CONCAT(pe.first_name,' ',pe.last_name) LIKE ? OR CONCAT(se.first_name,' ',se.last_name) LIKE ? OR p.card_last_four LIKE ?)";$q='%'.$search.'%';$types.='sssss';array_push($args,$q,$q,$q,$q,$q);}if(in_array($receipt,['attached','missing'],true)){$where.=' AND p.receipt_status=?';$types.='s';$args[]=$receipt;}return [$where,$types,$args];}
}
